// Keep the cloud quiz and map in sync with the playable educational content.
import { writeFile } from "node:fs/promises";
import { QUIZ, REVELATIONS } from "../js/content.js";
import { WORLD, PLAYER_START, ROOMS } from "../js/world.js";
import {
  COLORS,
  EMOTES,
  PREDICTIONS,
  REDS,
  predictionWins,
} from "../js/shared.js";
const values = {
  QUIZ,
  REVELATIONS: REVELATIONS.map(({ id }) => ({ id })),
  WORLD,
  PLAYER_START,
  ROOMS,
  COLORS,
  EMOTES,
  PREDICTIONS,
  REDS,
};
let content =
  "// Generated by node tools/cloud-content.mjs; edit the source content in js/.\n";
for (const [key, value] of Object.entries(values))
  content += `export const ${key} = ${JSON.stringify(value)};\n`;
content += `export const predictionWins = ${predictionWins.toString()};\n`;
content += `export function roomAt(x,y) { return ROOMS.find(r => x >= r.x && x < r.x+r.w && y >= r.y && y < r.y+r.h); }\n`;
await writeFile(
  new URL("../supabase/functions/casino/content.mjs", import.meta.url),
  content,
);
